mapper.select:
SELECT M.* FROM( SELECT suat.authority_trx_id, suat.document_category, suat.document_id, suat.user_id, suat.authority_source_id, suat.authority_source_type, suat.company_code, suat.unit_code, suat.position_code, ( SELECT DISTINCT fc.company_full_name FROM fnd_company fc WHERE fc.company_code = suat.company_code ) AS company_full_name, ( SELECT DISTINCT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_code = suat.unit_code ) AS unit_name, ( SELECT DISTINCT fop.position_name FROM fnd_org_position fop WHERE fop.position_code = suat.position_code -- positionCode可以重复，根据unit_code+position_code确定唯一岗位 and fop.unit_id = ( select unit_id from fnd_org_unit where unit_code = suat.unit_code ) ) AS position_name, ( SELECT su.description FROM sys_user su WHERE su.user_id = suat.user_id ) AS user_name, ( SELECT su.description FROM sys_user su WHERE su.user_id = suat.authority_source_id ) AS authority_source_name, CASE SUAT.DOCUMENT_CATEGORY WHEN 'HLS_BP_MASTER' THEN ( SELECT BP.BP_NAME FROM HLS_BP_MASTER bp WHERE bp.bp_id = SUAT.DOCUMENT_ID ) WHEN 'PRJ_CHANCE' THEN '商机' WHEN 'CON_CONTRACT' THEN ( SELECT con.contract_name FROM CON_CONTRACT con WHERE CON.contract_id = SUAT.DOCUMENT_ID ) WHEN 'PRJ_PROJECT' THEN ( SELECT prj.PROJECT_NAME FROM PRJ_PROJECT prj WHERE PRJ.PROJECT_ID = SUAT.DOCUMENT_ID ) WHEN 'HLS_CREDIT_LINE' THEN ( SELECT hcl.credit_line_NAME FROM HLS_CREDIT_LINE hcl WHERE hcl.credit_line_id = SUAT.DOCUMENT_ID ) WHEN 'FCT_PROJECT' THEN ( SELECT fp.project_name FROM fct_project fp WHERE fp.project_id = SUAT.DOCUMENT_ID ) WHEN 'FCT_CONTRACT' THEN ( SELECT fc.contract_name FROM fct_contract fc WHERE fc.contract_id = SUAT.DOCUMENT_ID ) END AS DOCUMENT_NAME, CASE SUAT.DOCUMENT_CATEGORY WHEN 'HLS_BP_MASTER' THEN ( SELECT BP.bp_code FROM HLS_BP_MASTER bp WHERE bp.bp_id = SUAT.DOCUMENT_ID ) WHEN 'PRJ_CHANCE' THEN ( SELECT pc.chance_number FROM prj_chance pc WHERE pc.chance_id = SUAT.DOCUMENT_ID ) WHEN 'CON_CONTRACT' THEN ( SELECT con.contract_number FROM CON_CONTRACT con WHERE CON.contract_id = SUAT.DOCUMENT_ID ) WHEN 'PRJ_PROJECT' THEN ( SELECT prj.project_number FROM PRJ_PROJECT prj WHERE PRJ.PROJECT_ID = SUAT.DOCUMENT_ID ) WHEN 'HLS_CREDIT_LINE' THEN ( SELECT hcl.credit_line_number FROM HLS_CREDIT_LINE hcl WHERE hcl.credit_line_id = SUAT.DOCUMENT_ID ) WHEN 'FCT_PROJECT' THEN ( SELECT fp.project_number FROM fct_project fp WHERE fp.project_id = SUAT.DOCUMENT_ID ) WHEN 'FCT_CONTRACT' THEN ( SELECT fc.contract_number FROM fct_contract fc WHERE fc.contract_id = SUAT.DOCUMENT_ID ) END AS DOCUMENT_CODE FROM sys_user_authority_trx suat
AND suat.document_category = #{documentCategory}
AND suat.document_id = #{documentId}
AND suat.company_code = #{companyCode}
AND suat.user_id = #{userId}
AND (suat.authority_source_id = #{authoritySourceId} or #{authoritySourceId} in ( SELECT SUA2.user_id FROM sys_user_allocation sua2 INNER JOIN fnd_employee_assigns fea2 ON sua2.employee_assign_id = FEA2.EMPLOYEE_ASSIGN_ID INNER JOIN fnd_org_position fop2 ON fea2.position_id = fop2.position_id WHERE fop2.chief_position_flag = 'Y' AND fop2.unit_id = ( SELECT unit_id FROM FND_EMPLOYEE_ASSIGNS fea3 INNER JOIN SYS_USER_ALLOCATION sua3 ON fea3.EMPLOYEE_ASSIGN_ID = SUA3.EMPLOYEE_ASSIGN_ID WHERE SUA3.user_id = suat.authority_source_id ) ) )
ORDER BY suat.creation_date DESC ) M

select fc.COMPANY_CODE as COMPANY_CODE, fou.unit_code as unit_code, fop.position_code as position_code, sua.user_id as user_id from fnd_employee_assigns fea INNER JOIN FND_COMPANY fc on fea.COMPANY_ID = fc.COMPANY_ID INNER JOIN FND_ORG_UNIT fou on fea.unit_id = fou.unit_id INNER JOIN FND_ORG_POSITION fop on fea.position_id = fop.position_id INNER JOIN SYS_USER_ALLOCATION sua on fea.employee_assign_id = sua.employee_assign_id
and fc.company_code=#{companyCode}
and fou.unit_code=#{unitCode}
and fop.position_code=#{positionCode}
and sua.user_id=#{userId}

select suat.authority_trx_id
FROM sys_user_authority_trx suat
where document_category = #{documentCategory}
and user_id = #{userId}
and document_id = #{documentId}

select suat.authority_trx_id,
suat.document_category,
suat.document_id,
suat.authority_source_type,
suat.authority_source_id,
suat.user_id
FROM sys_user_authority_trx suat
where document_category = #{documentCategory}
and document_id = #{documentId}
and user_id = #{userId}
